MODEL = os.environ.get('OPENAI_TRANSLATION_MODEL', 'gpt-4o-mini')


def translate_script(script: str, target_language: str, source_language: Optional[str] = None) -> str:
    client = OpenAI(api_key=os.environ.get('OPENAI_API_KEY'))
    prompt = f'Translate the following narration script into {target_language}.'
    if source_language:
        prompt += f' Source language: {source_language}.'
    resp = client.responses.create(model=MODEL, input=[{'role': 'system', 'content': 'You are a precise translation engine.'}, {'role': 'user', 'content': f'{prompt}\n\n{script}'}])
    return resp.output_text
","script_safety.py":"import os

from openai import OpenAI


MODEL = os.environ.get('OPENAI_SAFETY_MODEL', 'gpt-4o-mini')


def check_script_safety(script: str) -> dict:
    client = OpenAI(api_key=os.environ.get('OPENAI_API_KEY'))
    resp = client.responses.create(model=MODEL, input=[{'role': 'system', 'content': 'Classify narration script safety concerns.'}, {'role': 'user', 'content': script}])
    text = resp.output_text.lower()
    unsafe = any(term in text for term in ['unsafe', 'disallowed', 'violence', 'self-harm', 'hate'])
    return {'safe': not unsafe, 'analysis': resp.output_text}
